def frottement_adherence():
    p = [_txt(40, 26, "Pourquoi une pièce posée sur un plan incliné tient — jusqu'à un certain angle :",
              13, TRAIT, "start", True)]
    # plan incline
    p.append(f"<path d='M80,250 L420,250 L420,140 Z' fill='#e2e8f0' stroke='{TRAIT}' stroke-width='2'/>")
    # bloc
    p.append(f"<rect x='300' y='150' width='58' height='40' fill='#cbd5e1' stroke='{TRAIT}' stroke-width='2' transform='rotate(-17.9 329,170)'/>")
    # poids
    p.append(f"<line x1='329' y1='176' x2='329' y2='236' stroke='{ALERTE}' stroke-width='2.6' marker-end='url(#r1)'/>")
    p.append("<defs><marker id='r1' markerWidth='9' markerHeight='9' refX='8' refY='4.5' orient='auto'>"
             f"<path d='M0,0 L9,4.5 L0,9 z' fill='{ALERTE}'/></marker></defs>")
    p.append(_txt(336, 232, "P = mg", 11, ALERTE, "start", True))
    # angle
    p.append(f"<path d='M180,250 a 100,100 0 0,0 -2,-32' fill='none' stroke='{TRAIT}' stroke-width='1.3'/>")
    p.append(_txt(196, 238, "α", 13, TRAIT, "start", True))
    p.append(_txt(250, 275, "on incline peu à peu…", 11, FIN, "middle"))
    p.append(f"<rect x='450' y='60' width='270' height='190' rx='8' fill='#ffffff' stroke='{ALESAGE}' stroke-width='2'/>")
    p.append(_txt(585, 86, "Ce qui se passe", 12, ALESAGE, "middle", True))
    lignes = [("α petit", "la pièce ne bouge pas", OK),
              ("", "adhérence : T = P sin α", FIN),
              ("α augmente", "T augmente aussi", FIN),
              ("α = φ", "elle est sur le point de glisser", ARBRE),
              ("", "tan φ = f (coef. d'adhérence)", ARBRE),
              ("α > φ", "elle glisse, et T reste = f × N", ALERTE)]
    y = 112
    for g, d, couleur in lignes:
        if g:
            p.append(_txt(468, y, g, 11, couleur, "start", True))
        p.append(_txt(g and 545 or 480, y, d, 10, couleur if not g else FIN))
        y += 24
    p.append(f"<rect x='40' y='285' width='680' height='90' fill='#fff7ed' stroke='{ARBRE}' rx='6'/>")
    p.append(_txt(56, 308, "L'angle limite φ ne dépend NI de la masse, NI de la surface de contact :", 12, TRAIT, "start", True))
    p.append(_txt(56, 328, "il ne dépend que du couple de matériaux en contact. tan φ = f.", 12, FIN))
    p.append(_txt(56, 352, "Acier/acier sec f ≈ 0,15 (φ ≈ 8,5°) · acier/acier lubrifié 0,08 · acier/bronze 0,18 ·", 11, FIN))
    p.append(_txt(56, 368, "pneu/route sèche 0,8 · acier/glace 0,03", 11, FIN))
    return _svg("".join(p), 760, 390)


