# ===========================================================================
# 60. RÉSONANCE : LA COURBE D'AMPLIFICATION
# ===========================================================================

def resonance():
    import math as _m
    p = [_txt(40, 26, "Quand la fréquence d'excitation approche la fréquence propre, tout s'emballe :",
              13, TRAIT, "start", True)]
    ox, oy = 100, 280
    p.append(f"<line x1='{ox}' y1='{oy}' x2='660' y2='{oy}' stroke='{TRAIT}' stroke-width='1.5'/>")
    p.append(f"<line x1='{ox}' y1='{oy}' x2='{ox}' y2='60' stroke='{TRAIT}' stroke-width='1.5'/>")
    p.append(_txt(380, 312, "rapport f excitation / f propre", 11, FIN, "middle"))
    p.append(f"<text x='48' y='180' {_POLICE} font-size='11' fill='{FIN}' transform='rotate(-90 48,180)'>amplification</text>")
    # courbes pour deux amortissements
    for amort, couleur, label, ly in ((0.05, ALERTE, "peu amorti", 96), (0.25, OK, "bien amorti", 150)):
        pts = []
        for i in range(0, 141):
            x = i / 50.0
            val = 1 / _m.sqrt((1 - x * x) ** 2 + (2 * amort * x) ** 2)
            y = oy - min(val, 10) * 21
            pts.append(f"{ox + i * 4:.0f},{y:.1f}")
        p.append(f"<polyline points='{' '.join(pts)}' fill='none' stroke='{couleur}' stroke-width='2.6'/>")
        p.append(_txt(600, ly, label, 11, couleur, "start", True))
    # ligne de resonance
    p.append(f"<line x1='{ox + 200}' y1='70' x2='{ox + 200}' y2='{oy}' stroke='{FIN}' stroke-width='1.4' stroke-dasharray='6 4'/>")
    p.append(_txt(ox + 200, 60, "RÉSONANCE", 12, ALERTE, "middle", True))
    p.append(_txt(ox + 200, oy + 18, "1", 11, FIN, "middle"))
    p.append(_txt(ox, oy + 18, "0", 11, FIN, "middle"))
    p.append(_txt(ox + 400, oy + 18, "2", 11, FIN, "middle"))
    p.append(f"<rect x='40' y='330' width='680' height='90' fill='#fef2f2' stroke='{ALERTE}' rx='6'/>")
    p.append(_txt(56, 353, "f propre = (1/2π) √(k/m) — elle ne dépend QUE de la raideur et de la masse.", 12, TRAIT, "start", True))
    p.append(_txt(56, 375, "Deux parades : DÉCALER la fréquence propre (changer k ou m) ou AMORTIR.", 12, FIN))
    p.append(_txt(56, 397, "Renforcer une pièce qui vibre peut aggraver : cela déplace f propre, parfois vers l'excitation.",
                  11, ALERTE, "start", True))
    return _svg("".join(p), 760, 435)


