# 69. DE LA PIÈCE AU SCHÉMA : LA MÉTHODE EN TROIS TEMPS
# ===========================================================================

def methode_schema():
    p = [_txt(40, 24, "Un étau : quinze pièces réelles, trois groupes, trois liaisons.", 13, TRAIT, "start", True)]
    # temps 1 : classes
    p.append(_txt(120, 58, "1. CLASSES D'ÉQUIVALENCE", 11, ALESAGE, "middle", True))
    groupes = [(60, "S1", "corps + mors fixe + vis de fixation", FIN),
               (60, "S2", "vis de manœuvre + poignée + goupille", ALESAGE),
               (60, "S3", "mors mobile + écrou", ARBRE)]
    y = 80
    for x, nom, detail, couleur in groupes:
        p.append(f"<rect x='{x}' y='{y}' width='190' height='42' rx='6' fill='#ffffff' stroke='{couleur}' stroke-width='1.8'/>")
        p.append(_txt(x + 12, y + 18, nom, 12, couleur, "start", True))
        p.append(_txt(x + 12, y + 34, detail, 9, FIN))
        y += 52
    p.append(_txt(155, 246, "la visserie disparaît :", 10, ALERTE, "middle", True))
    p.append(_txt(155, 261, "elle crée un encastrement", 10, FIN, "middle"))
    # temps 2 : graphe
    p.append(_txt(400, 58, "2. GRAPHE DES LIAISONS", 11, ALESAGE, "middle", True))
    pts = {"S1": (400, 105), "S2": (340, 200), "S3": (462, 200)}
    for nom, (x, y) in pts.items():
        p.append(f"<circle cx='{x}' cy='{y}' r='24' fill='#ffffff' stroke='{TRAIT}' stroke-width='2'/>")
        p.append(_txt(x, y + 5, nom, 12, TRAIT, "middle", True))
    liens = [("S1", "S2", "pivot x"), ("S1", "S3", "glissière x"), ("S2", "S3", "hélicoïdale x")]
    for a, b, lbl in liens:
        (x1, y1), (x2, y2) = pts[a], pts[b]
        p.append(f"<line x1='{x1}' y1='{y1}' x2='{x2}' y2='{y2}' stroke='{ALESAGE}' stroke-width='1.8'/>")
        mx, my = (x1 + x2) / 2, (y1 + y2) / 2
        p.append(f"<rect x='{mx - 36}' y='{my - 9}' width='72' height='18' fill='{FOND}'/>")
        p.append(_txt(mx, my + 4, lbl, 9, ALESAGE, "middle", True))
    p.append(_txt(400, 250, "un cercle par groupe,", 10, FIN, "middle"))
    p.append(_txt(400, 264, "un trait par liaison", 10, FIN, "middle"))
    # temps 3 : schema
    p.append(_txt(620, 58, "3. SCHÉMA CINÉMATIQUE", 11, ALESAGE, "middle", True))
    p.append(f"<line x1='545' y1='170' x2='700' y2='170' stroke='{TRAIT}' stroke-width='2.4'/>")
    p.append(f"<rect x='556' y='150' width='22' height='20' fill='none' stroke='{TRAIT}' stroke-width='2'/>")
    p.append(_txt(567, 140, "pivot", 9, FIN, "middle"))
    p.append(f"<rect x='612' y='158' width='44' height='24' fill='none' stroke='{TRAIT}' stroke-width='2'/>")
    p.append(_txt(634, 196, "glissière", 9, FIN, "middle"))
    p.append(f"<path d='M666,158 l10,12 l-10,12' fill='none' stroke='{TRAIT}' stroke-width='2'/>")
    p.append(_txt(682, 140, "hélicoïdale", 9, FIN, "middle"))
    p.append(_txt(620, 250, "on dessine les MOUVEMENTS,", 10, FIN, "middle"))
    p.append(_txt(620, 264, "jamais les formes", 10, FIN, "middle"))
    p.append(f"<rect x='40' y='285' width='680' height='68' fill='#f0fdf4' stroke='{OK}' rx='6'/>")
    p.append(_txt(56, 308, "Lecture du schéma obtenu : la rotation de la vis (pivot) devient une translation", 12, TRAIT, "start", True))
    p.append(_txt(56, 328, "du mors (glissière), grâce à la liaison hélicoïdale. C'est un transformateur de", 12, FIN))
    p.append(_txt(56, 346, "mouvement — et cela se lit sans connaître la forme d'aucune pièce.", 12, FIN))
    return _svg("".join(p), 760, 375)


