    p.append(_txt(658, 114, "portée Ra 0,8", 9, FIN, "start"))
    decisions = [
        ("1", "quelle bague serrée ?", "charge tournante → bague intérieure : arbre k6, alésage H7", ARBRE),
        ("2", "quel palier fixe ?", "UN SEUL — l'autre doit coulisser pour la dilatation", OK),
        ("3", "quels arrêts axiaux ?", "épaulement d'un côté, anneau élastique de l'autre", TRAIT),
        ("4", "quelle lubrification ?", "graisse au tiers du volume libre, ou roulements 2RS", ALESAGE),
        ("5", "quelle étanchéité ?", "joint à lèvres, lèvre vers l'intérieur, portée Ra 0,8", ALERTE),
    ]
    y = 205
    for num, question, reponse, couleur in decisions:
        p.append(f"<circle cx='72' cy='{y - 4}' r='11' fill='{couleur}'/>")
        p.append(_txt(72, y, num, 11, "#ffffff", "middle", True))
        p.append(_txt(92, y, question, 11, couleur, "start", True))
        p.append(_txt(262, y, reponse, 11, FIN))
        y += 30
    p.append(f"<rect x='40' y='350' width='680' height='48' fill='#fef2f2' stroke='{ALERTE}' rx='6'/>")
    p.append(_txt(56, 372, "Le détail qui tue : le rayon du congé d'épaulement doit être INFÉRIEUR à celui de", 12, TRAIT, "start", True))
    p.append(_txt(56, 390, "la bague — sinon elle porte sur l'arrondi et se monte de travers.", 12, FIN))
    return _svg("".join(p), 760, 415)


