METHODES = {}


def _mth(fiche_id, titre, etapes, exemple):
    lignes = [f"### {titre}", ""]
    for i, e in enumerate(etapes, 1):
        lignes.append(f"{i}. {e}")
    lignes += ["", f"> **Sur un exemple.** {exemple}"]
    METHODES[fiche_id] = "\n".join(lignes)


